export const foreshadowStyle=`
.sf-page{--sf-line:color-mix(in srgb,var(--ink,#243e59) 13%,transparent);--sf-muted:var(--muted,#728398);--sf-surface:var(--panel,#fff);flex:1;min-height:0;overflow:auto;padding:24px clamp(16px,3vw,44px) 36px;container-type:inline-size}.sf-page *,.sf-dialog *{box-sizing:border-box}.sf-toolbar{display:flex;align-items:center;gap:14px;margin:0 0 22px}.sf-toolbar small{color:var(--sf-muted);font-size:11px;letter-spacing:.12em}.sf-toolbar h2{font-size:25px;margin:3px 0 0;font-weight:650;letter-spacing:.05em}.sf-total{color:var(--sf-muted);font-size:12px}.sf-toolbar>button{margin-left:auto}.sf-page button,.sf-dialog button{border-radius:9px;font-size:12px;min-height:34px;cursor:pointer}.sf-primary{background:#3569ad!important;color:#fff!important;border:1px solid #3569ad!important;padding:8px 15px!important}.sf-controls{display:flex;gap:20px;align-items:center;margin-bottom:22px;flex-wrap:wrap}.sf-controls>input{width:230px;border-radius:10px;padding:10px 13px;background:var(--sf-surface);border:1px solid var(--sf-line)}.sf-filters{display:flex;gap:4px;flex-wrap:wrap}.sf-filters button{background:none;border:0;padding:6px 11px;color:var(--sf-muted)}.sf-filters button[aria-pressed=true]{background:#dfeafb;color:#24528a}.sf-list{display:grid;gap:22px;max-width:1200px;margin:auto}.sf-card{border:1px solid var(--sf-line);border-radius:17px;background:var(--sf-surface);box-shadow:0 4px 18px #17385d05;overflow:hidden}.sf-card[data-focused=true]{border-color:#8caedb;box-shadow:0 0 0 3px #5086cd12}.sf-card>header{display:flex;gap:14px;padding:22px 24px 18px;align-items:flex-start}.sf-mark{display:grid;place-items:center;flex-shrink:0;width:40px;height:40px;background:#eef1fb;color:#6177b0;border-radius:13px;font-size:27px}.sf-title{flex:1;min-width:0}.sf-title h3{margin:0 0 6px;font-size:17px;line-height:1.5;font-weight:650}.sf-title p{margin:0;font-size:12px;line-height:1.8;color:var(--sf-muted);white-space:pre-wrap;overflow-wrap:anywhere}.sf-status{white-space:nowrap;border-radius:20px;padding:5px 10px;font-size:11px;background:#edf1f6;color:#60758b}.sf-status[data-state=partial]{background:#fcf0db;color:#96703b}.sf-status[data-state=recovered]{background:#e6f3ed;color:#327456}.sf-status[data-state=open]{background:#eeebf8;color:#7a689e}.sf-stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding:0 24px 22px}.sf-stage{--stage:#7487b2;min-width:0}.sf-stage[data-kind=progress]{--stage:#3e958e}.sf-stage[data-kind=recover]{--stage:#b28b4f}.sf-stage h4{display:flex;align-items:center;gap:9px;border-bottom:2px solid color-mix(in srgb,var(--stage) 32%,transparent);margin:0 0 13px;padding:10px 0;color:var(--stage);font-size:12px}.sf-stage h4>span{font-size:11px;font-weight:400;opacity:.8}.sf-stage h4>small{margin-left:auto;font-weight:400}.sf-stage-nodes{display:grid;gap:9px}.sf-empty-stage{margin:0;padding:15px 0 19px;font-size:12px;color:var(--sf-muted);opacity:.75}.sf-node{border:1px dashed color-mix(in srgb,var(--stage) 35%,transparent);border-left:3px solid var(--stage);border-radius:10px;padding:10px 12px;background:color-mix(in srgb,var(--stage) 5%,var(--sf-surface))}.sf-node[data-fact=true]{border-style:solid}.sf-node-meta{display:flex;justify-content:space-between;gap:6px;align-items:center;font-size:10px;color:var(--stage)}.sf-node-meta button{border:0;background:none;color:var(--sf-muted);min-height:26px;padding:2px 5px;font-size:10px}.sf-node .sf-plot-link{display:block;width:100%;text-align:left;background:none;border:0;border-radius:0;padding:3px 0;min-height:30px;line-height:1.6;font-size:13px;font-weight:550;white-space:normal}.sf-node>small{display:block;color:var(--sf-muted);font-size:10px}.sf-node>p{font-size:12px;line-height:1.7;margin:10px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.sf-node .sf-evidence-link{border:0;background:none;padding:7px 0 0;color:var(--stage);font-size:10px;line-height:1.6;min-height:28px;text-align:left}.sf-details>footer{display:flex;align-items:center;gap:12px;padding:12px 24px;border-top:1px solid var(--sf-line);background:color-mix(in srgb,#7289af 3%,transparent)}.sf-details>footer>span{color:var(--sf-muted);font-size:11px}.sf-details>footer>div{display:flex;gap:5px;margin-left:auto}.sf-details>footer button{border:0;background:none;padding:6px 9px}.sf-details>footer .sf-add{background:#edf3fc;color:#3569ad}.sf-review{background:#fff5df;color:#885f27;border-radius:9px;padding:10px 14px;font-size:12px;line-height:1.7}.sf-details>.sf-review{margin:0 24px 15px}.sf-earlier{padding:0 24px 18px;font-size:12px;color:var(--sf-muted)}.sf-earlier q{display:block;margin:8px 0}.sf-context{display:flex;gap:12px;align-items:center;border-radius:10px;padding:10px 15px;background:#e9f1ff;margin-bottom:20px;font-size:12px}.sf-empty{text-align:center;padding:45px;color:var(--sf-muted)}.sf-empty>span{font-size:42px}.sf-empty h3{font-size:16px}.sf-empty p{font-size:12px}.sf-dialog{width:min(620px,calc(100vw - 24px))!important}.sf-form{display:grid;gap:18px;padding:4px 2px 10px}.sf-form-intro,.sf-help{font-size:12px;line-height:1.8;color:var(--muted,#728398);margin:0}.sf-form>label,.sf-form-grid>label,.sf-proof>label{display:grid;gap:8px;font-size:12px}.sf-form input:not([type=radio]),.sf-form textarea,.sf-form select{width:100%;max-width:100%;padding:10px 12px;border:1px solid color-mix(in srgb,currentColor 18%,transparent);border-radius:9px;background:var(--panel,#fff);color:inherit;font:inherit}.sf-form textarea{min-height:100px;resize:vertical;line-height:1.7}.sf-form-grid{display:grid;grid-template-columns:100px minmax(0,1fr);gap:15px}.sf-mode{display:flex;border-radius:10px;background:#eaf0f8;padding:4px;gap:4px}.sf-mode button{flex:1;border:0;background:none;color:#667d9d}.sf-mode button[aria-pressed=true]{background:var(--panel,#fff);color:#285d9d;box-shadow:0 2px 5px #25456910}.sf-proof{display:grid;gap:14px;background:color-mix(in srgb,#5a86bd 5%,transparent);padding:17px;border-radius:12px}.sf-proof p,.sf-proof summary{font-size:12px;line-height:1.7;margin:0}.sf-proof pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.9 inherit;max-height:150px;overflow:auto;margin:10px 0}.sf-proof small{font-size:11px;color:#946d31}.sf-resolution{display:flex!important;gap:12px!important;align-items:flex-start;border:1px solid #bdcde155;border-radius:12px;padding:15px}.sf-resolution input{margin-top:4px}.sf-resolution span{display:grid;gap:6px}.sf-resolution small{font-size:12px;line-height:1.7;color:var(--muted,#728398)}.sf-form-actions{display:flex;gap:8px;justify-content:flex-end;align-items:center;padding-top:14px;border-top:1px solid #9aadc333}.sf-form-actions .sf-danger{margin-right:auto;color:#ad594f;background:none;border:0}.sf-plot-section{padding:16px;border-radius:12px;background:#668bb50a}.sf-plot-section h3{font-size:13px;margin:0 0 12px}.sf-plot-section>button{display:flex;gap:12px;justify-content:space-between;width:100%;text-align:left;margin:6px 0;border-radius:8px}.sf-plot-section small{font-size:11px;color:var(--muted,#728398)}
@container(max-width:650px){.sf-stages{grid-template-columns:1fr;gap:7px;padding:0 18px 18px}.sf-stage{display:grid;grid-template-columns:55px minmax(0,1fr);gap:13px}.sf-stage h4{display:flex;flex-direction:column;justify-content:flex-start;border:0;border-right:2px solid color-mix(in srgb,var(--stage) 26%,transparent);margin:0;padding:8px 10px 8px 0;gap:5px}.sf-stage h4>small{margin:0}.sf-empty-stage{padding:20px 0}.sf-card>header{display:grid;grid-template-columns:34px minmax(0,1fr);padding:18px;gap:10px}.sf-mark{width:34px;height:34px;font-size:23px}.sf-title h3{font-size:15px}.sf-status{grid-column:2;justify-self:start;font-size:10px;padding:4px 8px;margin:0}.sf-details>footer{padding:12px 15px;gap:7px;flex-wrap:wrap}.sf-details>footer>span{font-size:10px}.sf-details>footer>div{width:100%;justify-content:flex-end}.sf-toolbar{margin-bottom:17px;gap:8px}.sf-toolbar h2{font-size:22px}.sf-toolbar small{font-size:10px}.sf-total{display:none}.sf-controls{gap:10px}.sf-controls>input{width:100%}.sf-filters{gap:2px}.sf-filters button{padding:6px 9px;font-size:11px}.sf-review{margin:0 18px 12px}.sf-context{align-items:flex-start}.sf-empty{padding:35px 12px}}
@media(max-width:500px){.sf-page{padding:16px 12px 24px}.sf-form-grid{grid-template-columns:85px minmax(0,1fr)}.sf-proof{padding:12px}.sf-dialog{width:calc(100vw - 16px)!important}.sf-form-actions button{min-height:40px}.sf-node-meta button{min-height:32px;min-width:35px}}

.sf-card{--sf-state:#75869d}.sf-card[data-state=planted]{--sf-state:#687fb1}.sf-card[data-state=developing]{--sf-state:#328a83}.sf-card[data-state=partial]{--sf-state:#aa7c34}.sf-card[data-state=recovered]{--sf-state:#3c8461}.sf-card[data-state=open]{--sf-state:#8970ac}.sf-card[data-state=abandoned]{--sf-state:#85858b}
.sf-card .sf-mark{background:color-mix(in srgb,var(--sf-state) 10%,var(--sf-surface));color:var(--sf-state)}.sf-summary{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:10px}.sf-summary .sf-status{background:color-mix(in srgb,var(--sf-state) 11%,var(--sf-surface));color:var(--sf-state);border:1px solid color-mix(in srgb,var(--sf-state) 13%,transparent);font-size:11px;padding:3px 9px;line-height:1.6}.sf-summary>small{font-size:11px;color:var(--sf-muted)}.sf-review-badge{font-size:10px;color:#946528;background:#fff2d9;padding:3px 7px;border-radius:6px}.sf-card .sf-toggle{display:flex;align-items:center;gap:5px;flex-shrink:0;border:0;background:transparent;color:var(--sf-muted);padding:5px 8px;min-height:36px;white-space:nowrap}.sf-card .sf-toggle:hover{background:color-mix(in srgb,var(--sf-state) 8%,transparent);color:var(--sf-state)}.sf-toggle svg{width:14px;height:14px;min-width:14px;max-width:none;flex:0 0 14px;border:0;border-radius:0;transition:transform .15s}.sf-toggle[aria-expanded=true] svg{transform:rotate(180deg)}.sf-details[hidden]{display:none!important}.sf-card[data-expanded=false]>header{padding-top:16px;padding-bottom:16px}.sf-card[data-expanded=false] .sf-title h3{margin-bottom:0;font-size:15px}.sf-card[data-expanded=false] .sf-summary{margin-top:7px}.sf-list{gap:14px}
@container(max-width:650px){.sf-card>header{grid-template-columns:34px minmax(0,1fr) 58px;gap:10px}.sf-card .sf-toggle{grid-column:3;grid-row:1;padding:4px;min-height:36px;font-size:11px}.sf-summary{gap:7px}.sf-summary .sf-status{grid-column:auto;font-size:10px}.sf-summary>small{font-size:10px}.sf-card[data-expanded=false]>header{padding:14px}.sf-card[data-expanded=false] .sf-title h3{font-size:14px}.sf-card .sf-title h3{overflow-wrap:anywhere}}
@media(prefers-reduced-motion:reduce){.sf-toggle svg{transition:none}}

`;
